solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <map>
#include <optional>
#include <sstream>
#include <string>

struct Endpoint { std::string host; std::uint16_t port; };
struct PortFile { std::uint16_t port; std::uint32_t pid; std::string token; };

static bool allDigits(const std::string& s)
{
    if (s.empty() || s.size() > 10) return false;
    for (char c : s) if (!std::isdigit(static_cast<unsigned char>(c))) return false;
    return true;
}

static std::optional<std::uint16_t> port(const std::string& s)
{
    if (!allDigits(s) || s.size() > 5) return std::nullopt;
    const unsigned long v{ std::stoul(s) };
    if (v < 1 || v > 65535) return std::nullopt;
    return static_cast<std::uint16_t>(v);
}

bool isLoopback(const std::string& host)
{
    std::string lower{ host };
    for (char& c : lower) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    if (lower == "localhost" || lower == "::1") return true;
    std::istringstream in{ host };
    std::string part;
    int count{ 0 };
    int first{ -1 };
    while (std::getline(in, part, '.'))
    {
        if (!allDigits(part) || part.size() > 3 || std::stoi(part) > 255) return false;
        if (count == 0) first = std::stoi(part);
        ++count;
    }
    return count == 4 && first == 127 && host.back() != '.';
}

std::optional<Endpoint> parseEndpoint(const std::string& text)
{
    std::string host, rest;
    if (!text.empty() && text[0] == '[')
    {
        const std::size_t close{ text.find("]:") };
        if (close == std::string::npos) return std::nullopt;
        host = text.substr(1, close - 1);
        rest = text.substr(close + 2);
    }
    else
    {
        const std::size_t colon{ text.rfind(':') };
        if (colon == std::string::npos) return std::nullopt;
        host = text.substr(0, colon);
        rest = text.substr(colon + 1);
        if (host.find(':') != std::string::npos) return std::nullopt;
    }
    const auto p{ port(rest) };
    if (!p || !isLoopback(host)) return std::nullopt;
    return Endpoint{ host, *p };
}

std::string writePortFile(const PortFile& f)
{
    return "port=" + std::to_string(f.port) + "\npid=" + std::to_string(f.pid) + "\ntoken=" + f.token + "\n";
}

std::optional<PortFile> readPortFile(const std::string& text)
{
    std::map<std::string, std::string> values;
    std::istringstream in{ text };
    std::string line;
    while (std::getline(in, line))
    {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        if (line.empty()) continue;
        const std::size_t eq{ line.find('=') };
        if (eq == std::string::npos) return std::nullopt;
        const std::string key{ line.substr(0, eq) };
        if (values.count(key)) return std::nullopt;
        values[key] = line.substr(eq + 1);
    }
    if (values.size() != 3 || !values.count("port") || !values.count("pid") || !values.count("token")) return std::nullopt;
    const auto p{ port(values["port"]) };
    if (!p || !allDigits(values["pid"]) || std::stoull(values["pid"]) > 0xFFFFFFFFull) return std::nullopt;
    const std::string& token{ values["token"] };
    if (token.size() != 32) return std::nullopt;
    for (char c : token) if (!std::isdigit(static_cast<unsigned char>(c)) && (c < 'a' || c > 'f')) return std::nullopt;
    return PortFile{ *p, static_cast<std::uint32_t>(std::stoull(values["pid"])), token };
}

unitTests:
static const std::string TOKEN{ "0f3a9c2e7b1d4a6f8e2c0b9d7a5f3e1c" };
TEST("loopback hosts") {
    CHECK(isLoopback("127.0.0.1"));
    CHECK(isLoopback("127.12.0.254"));
    CHECK(isLoopback("LocalHost"));
    CHECK(isLoopback("::1"));
    CHECK(!isLoopback("0.0.0.0"));
    CHECK(!isLoopback("192.168.1.20"));
    CHECK(!isLoopback("127.0.0.256"));
    CHECK(!isLoopback("127.0.0"));
    CHECK(!isLoopback("127.0.0.1.evil.com"));
}
TEST("endpoints") {
    const auto a{ parseEndpoint("127.0.0.1:50123") };
    CHECK(a.has_value());
    if (a) { CHECK_EQ(a->host, std::string("127.0.0.1")); CHECK_EQ(a->port, 50123); }
    const auto b{ parseEndpoint("[::1]:8080") };
    if (b) CHECK_EQ(b->host, std::string("::1"));
    CHECK(b.has_value());
    CHECK(!parseEndpoint("10.0.0.5:50123").has_value());
    CHECK(!parseEndpoint("127.0.0.1:0").has_value());
    CHECK(!parseEndpoint("127.0.0.1:70000").has_value());
    CHECK(!parseEndpoint("127.0.0.1").has_value());
    CHECK(!parseEndpoint("::1:80").has_value());
}
TEST("port files") {
    const std::string text{ writePortFile({ 50123, 4120, TOKEN }) };
    CHECK_EQ(text, "port=50123\npid=4120\ntoken=" + TOKEN + "\n");
    const auto f{ readPortFile("token=" + TOKEN + "\r\n\r\npid=88\r\nport=1\r\n") };
    CHECK(f.has_value());
    if (f) { CHECK_EQ(f->port, 1); CHECK_EQ(f->pid, 88u); CHECK_EQ(f->token, TOKEN); }
}
TEST("bad port files") {
    CHECK(!readPortFile("port=50123\npid=4120\n").has_value());
    CHECK(!readPortFile("port=50123\npid=4120\ntoken=" + TOKEN + "\nport=1\n").has_value());
    CHECK(!readPortFile("port=50123\npid=x\ntoken=" + TOKEN + "\n").has_value());
    CHECK(!readPortFile("port=50123\npid=1\ntoken=ABC\n").has_value());
    CHECK(!readPortFile("port=50123\npid=1\ntoken=" + std::string(32, 'G') + "\n").has_value());
    CHECK(!readPortFile("port=0\npid=1\ntoken=" + TOKEN + "\n").has_value());
}

